235	/// Parses the contents of a mathematical equation: `x^2 + 1`.
236	fn math(p: &mut Parser, stop_set: SyntaxSet) {
237	    let m = p.marker();
238	    math_exprs(p, stop_set);
239	    p.wrap(m, SyntaxKind::Math);
240	}
