927	            p.with_nl_mode(AtNewline::Continue, |p| {
928	                let m2 = p.marker();
929	                p.assert(SyntaxKind::LeftParen);
930	
931	                import_items(p);
932	
933	                p.expect_closing_delimiter(m2, SyntaxKind::RightParen);
934	            });
935	        } else if !p.eat_if(SyntaxKind::Star) {
936	            import_items(p);
937	        }
